import{_ as r,h as n,i as e,c as s,v as t,p as i,x as o,m as E,e as p,S as B}from"./chunks/framework.Dvtg8yj2.js";const C=JSON.parse('{"title":"减少数据搬运、让利用率贴近峰值","description":"","frontmatter":{"title":"减少数据搬运、让利用率贴近峰值","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/jalapeno-data-movement.md","filePath":"llm/jalapeno-data-movement.md","lastUpdated":1788454257000}'),m={name:"llm/jalapeno-data-movement.md"};function d(h,a,A,c,P,T){const l=n("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="减少数据搬运、让利用率贴近峰值" tabindex="-1">减少数据搬运、让利用率贴近峰值 <a class="header-anchor" href="#减少数据搬运、让利用率贴近峰值" aria-label="Permalink to &quot;减少数据搬运、让利用率贴近峰值&quot;">​</a></h1><div class="epigraph"><p>峰值 FLOPS 只在数据已经在运算单元旁边时存在。长延迟路径、争用的统一内存和昂贵的全局栅栏，会让计算单元在数据路上空转。</p><footer>—— Hot Chips 2026 Jalapeño 架构叙述：把数据放在需要它的地方、在需要的时刻到达，减少空等</footer></div><p><a href="/llm/jalapeno-inference-only">推理专用</a> 把指标收成延迟与焦耳。本篇写 OpenAI 给出的机制性原因：观察到的延迟往往被<strong>架构造成的等待</strong>主导，而不是被矩阵单元的峰值时钟主导。Jalapeño 被说成 memory-sliced：每个核有自己那一份 HBM 的本地视图；常见跨核模式走专用低延迟集合网络，其余走更灵活的通用 NoC。公开规格里单封装 15.4 TB/s HBM4、216 GiB，128 芯片聚合带宽被讲者用来估算「若只看带宽天花板」的每用户 token 率，并立刻承认真实系统远低于该天花板——也就是说，<strong>搬得动不等于用得满</strong>。不确定的微架构参数（切片数、NoC 频率）不编造。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>逐步推理的算术强度低：每步要见权重与不断变长的 KV，见<a href="/llm/decode-memory-wall">显存墙</a>。GPU 用缓存与运行时 DMA 去猜下一拍；猜错就是暂停。OpenAI 把失败模式说得很具体：长延迟路径、被争用的统一内存子系统、昂贵的全局内存栅栏，都会让计算单元等「还在路上的数据」，利用率掉到峰值以下。HBM4 把带宽抬到 15.4 TB/s 量级之后，若核心仍通过一个过载的共享交叉去够所有字节，墙只是从「HBM 不够」变成「片上调度不够」。</p><p>128 芯片聚合超过 1 PB/s 的带宽，按讲者的粗算，若没有投机、只看带宽，可能暗示每用户 1000–2000 tokens/s 量级；加上投机 5000–10000。真实系统明显更低。这个对比的教学意义是：再买带宽，若不改数据放置与同步，利用率仍贴不近峰值。Jalapeño 的设计问题因此不是「如何公布更高 TB/s」，而是如何让操作数本地、让集合通信走专用短路、让栅栏变便宜或消失。</p><h3 id="本地视图对抗统一内存幻想" tabindex="-1">本地视图对抗统一内存幻想 <a class="header-anchor" href="#本地视图对抗统一内存幻想" aria-label="Permalink to &quot;本地视图对抗统一内存幻想&quot;">​</a></h3><p>「统一 HBM 池、任何核随便 load」在编程上舒服，在物理上等于所有流量挤进同一套一致性或同一套交叉开关。memory-sliced 的意思是：每个核默认只快看自己的切片；跨切片是显式通信，而不是隐式缓存填充。这与 GPU 的缓存一致性编程模型不同，也与「整颗芯片一个共享 SRAM」的 LPU 不同。代价是编译器必须把张量布局写进物理位置——公开说 tensor layout 显式捕获放置，Gluon 把核当 thread block。人要理解「数据在哪」；模型搜索负责把放置与流水排好。</p><p><span class="marginnote">后续题目会写「每核本地 HBM 视图 + 集合网络」的切片细节。本篇只锁定动机：减少搬运与空等。不要在本篇填写未公开的每核 HBM 容量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公开方法分成三层。封装内：核与 HBM 切片配对，常用操作数尽量不出切片。芯片内：专用集合网络服务常见跨核模式（可理解为为 TP / 规约这类规则通信准备的短路），通用 NoC 服务其余。芯片间：本地 128 卡高带宽域给张量并行，全局 2048 卡较低带宽给专家并行，避免所有通信都走同一档延迟。阶段门控则减少「单元闲着仍占数据路径底噪」——闲置不搬，也是一种减少搬运。</p><p>软件上，从功能正确的核出发，用内部系统去搜映射、放置、调度与流水。公开称注意力与 MoE 核相对专家手写快约 1.5×–1.8×，验证在芯片上端到端做。这暗示瓶颈确实在数据移动与调度，而不只在矩阵峰值：手写专家已经会写矩阵乘，搜索提升的是放置与流水。编程模型故意暴露本地张量与显式通信，让搜索空间可被机器遍历，而不是隐藏在缓存启发式里。</p>',12)),(e(),i(B,null,{default:o(()=>[p(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E7%AD%89%E5%BE%85%EF%BC%9A%E9%95%BF%E8%B7%AF%E5%BE%84%20%2F%20%E4%BA%89%E7%94%A8%20%2F%20%E6%A0%85%E6%A0%8F%22%5D%20--%3E%20U%5B%22%E5%88%A9%E7%94%A8%E7%8E%87%E8%BF%9C%E7%A6%BB%E5%B3%B0%E5%80%BC%22%5D%0A%20%20SLICE%5B%22%E6%A0%B8%20%2B%20%E6%9C%AC%E5%9C%B0%20HBM%20%E5%88%87%E7%89%87%22%5D%20--%3E%20LOC%5B%22%E6%93%8D%E4%BD%9C%E6%95%B0%E6%9C%AC%E5%9C%B0%22%5D%0A%20%20COL%5B%22%E4%B8%93%E7%94%A8%E9%9B%86%E5%90%88%E7%BD%91%E7%BB%9C%22%5D%20--%3E%20FAST%5B%22%E8%A7%84%E5%88%99%E9%80%9A%E4%BF%A1%E8%B5%B0%E7%9F%AD%E8%B7%AF%22%5D%0A%20%20NOC%5B%22%E9%80%9A%E7%94%A8%20NoC%22%5D%20--%3E%20REST%5B%22%E5%85%B6%E4%BD%99%E6%B5%81%E9%87%8F%22%5D%0A%20%20LOC%20--%3E%20PEAK%5B%22%E8%AE%A1%E7%AE%97%E5%8D%95%E5%85%83%E5%B0%91%E7%A9%BA%E7%AD%89%22%5D%0A%20%20FAST%20--%3E%20PEAK%0A%20%20PEAK%20--%3E%20TOK%5B%22%E5%BB%B6%E8%BF%9F%E4%B8%8E%E7%84%A6%E8%80%B3%E6%94%B9%E5%96%84%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="带宽天花板只用来做反证" tabindex="-1">带宽天花板只用来做反证 <a class="header-anchor" href="#带宽天花板只用来做反证" aria-label="Permalink to &quot;带宽天花板只用来做反证&quot;">​</a></h3><p>用 15.4 TB/s 去除以每 token 要搬的字节，可以得到一个假想 TPOT。OpenAI 把这个假想值摆出来，是为了说明「我们并未活在带宽屋顶上」。工程上应把同样的方法用在自己的模型：写出一步 decode 的权重字节 + KV 字节 + 激活交换字节，除以<strong>有效</strong>带宽（不是峰值），再与矩阵时间取大。有效带宽在切片架构里是本地切片带宽；跨切片与跨芯片的部分用 600 GB/s / 200 GB/s 的公开域口径去估。若激活交换接近这些口径，<a href="/llm/groq-3-lpx">AFD 式拆分</a> 或过宽的 EP 会先打满网络，矩阵单元继续空等——这正是 Jalapeño 要用专用集合网络去防的事。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>利用率 \\(\\eta \\approx T_{\\mathrm{compute}} / (T_{\\mathrm{compute}} + T_{\\mathrm{stall}})\\)。\\(T_{\\mathrm{stall}}\\) 来自远量子、锁与拥塞。切片把大多数访问的跳数降到 0（本地 HBM）；集合网络把规约/广播的跳数与争用从通用 NoC 里拿开；显式放置让编译器把 \\(T_{\\mathrm{stall}}\\) 编进时间表而不是在运行时发现。门控让不用的数据路径不参与争用。于是 \\(\\eta\\) 可以靠近峰值，而不要求峰值本身是世界第一——公开 13.4 PFLOP/s MXFP4 相对同节点训练 GPU 的宣传峰值并不以「更大」为卖点，卖点是<strong>用得上</strong>。</p><p>对 MoE，突发 All-to-All 是经典的利用率杀手：专家一切换，权重与 token 都要搬家。公开拓扑把 EP 放到全局域、带宽较低，说明他们接受跨 2048 的专家并行更稀、更不能每步全交换。能做的是：专家尽量落在本地 128 域，或接受较低的全局带宽并靠门控与调度避免热线。具体放置策略未公开，不要写成已经实现了某种动态专家迁移算法。</p><p><span class="marginnote">「减少数据搬运」不是减少数学上的 FLOPs，而是减少跨切片、跨芯片、跨阶段（KV 搬家）的字节。FLOPs 仍在；空等下降。与 FlashAttention 减少 HBM 往返是同一类动机，层次不同。</span></p><h3 id="和投机、mtp-的关系" tabindex="-1">和投机、MTP 的关系 <a class="header-anchor" href="#和投机、mtp-的关系" aria-label="Permalink to &quot;和投机、MTP 的关系&quot;">​</a></h3><p>投机解码用额外计算换更少的大模型逐步扫描，本质上也是减少「大权重重复搬运」。OpenAI 演示多用单 token 路径，并声称 MTP 还能在同等效率下再降延迟。那是算法层减搬运；本篇是硬件层减搬运。两者叠加时，不要把 InferenceX 上 STP 的每千瓦倍数，解释成已经包含 MTP。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>切片与显式通信提高了编程难度：错误的布局会让所有流量打到通用 NoC，芯片退化成「很贵的带宽很差的 GPU」。没有 CUDA 式隐式缓存来救拙劣内核。公开 bring-up 三个模型，不能外推到任意动态图。不要编造 NoC 拓扑（mesh 还是 crossbar）、不要填写未公开的片上 SRAM 每核容量。HBM4 的 216 GiB 是封装容量，决定能放下的权重+KV；切多少模型并行，仍受这张容量表约束。</p><p>若工作负载是极大 batch 的离线 prefill，统一内存 + 通用 GPU 可能更省事：算术强度高，\\(T_{\\mathrm{stall}}\\) 被计算盖住。Jalapeño 的搬运故事主要针对交互式、阶段混合、KV 不能乱搬家的服务。</p><p><span class="marginnote">出处：Hot Chips 2026 现场报道中关于 memory-sliced、本地 HBM 视图、集合网络与通用 NoC、带宽天花板 vs 真实 token 率的幻灯叙述。规格数字同场：15.4 TB/s、216 GiB、128/2048 域。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>公开诊断：空等来自远数据、争用内存与全局栅栏，使利用率离开峰值。</li><li>对策是切片本地视图、规则通信走专用集合网、其余走 NoC，KV 不在异构机群间搬。</li><li>峰值 HBM 带宽用来证明「真实系统不在带宽屋顶上」，规划要用有效带宽。</li><li>编译器显式放置是利用率的一部分，不是可选优化。</li><li>EP 的全局带宽更低，过宽的逐步 All-to-All 仍会打满网络。</li><li>出处：Hot Chips 2026 Jalapeño 架构报道。</li></ul>',14))])}const u=r(m,[["render",d]]);export{C as __pageData,u as default};
